<?php session_start();require 'koneksi.php';require_admin();$msg='';if(isset($_GET['hapus_produk'])){$id=(int)$_GET['hapus_produk'];mysqli_query($koneksi,"DELETE FROM produk WHERE id_produk=$id");$msg='Produk dihapus.';}if(isset($_POST['produk'])){$id=(int)($_POST['id']??0);$nama=trim($_POST['nama']);$harga=(float)$_POST['harga'];$stok=(int)$_POST['stok'];$kat=(int)$_POST['kategori'];$desk=trim($_POST['deskripsi']);if($id){$s=mysqli_prepare($koneksi,'UPDATE produk SET nama_produk=?,harga=?,stok=?,id_kategori=?,deskripsi=? WHERE id_produk=?');mysqli_stmt_bind_param($s,'sdiisi',$nama,$harga,$stok,$kat,$desk,$id);}else{$s=mysqli_prepare($koneksi,'INSERT INTO produk(nama_produk,harga,stok,id_kategori,deskripsi) VALUES(?,?,?,?,?)');mysqli_stmt_bind_param($s,'sdiis',$nama,$harga,$stok,$kat,$desk);}mysqli_stmt_execute($s);$msg='Produk berhasil disimpan.';}if(isset($_POST['kategori'])){$nama=trim($_POST['nama_kategori']);$s=mysqli_prepare($koneksi,'INSERT INTO kategori(nama_kategori) VALUES(?)');mysqli_stmt_bind_param($s,'s',$nama);mysqli_stmt_execute($s);$msg='Kategori ditambahkan.';}$cats=mysqli_query($koneksi,'SELECT * FROM kategori ORDER BY nama_kategori');$products=mysqli_query($koneksi,'SELECT p.*,k.nama_kategori FROM produk p LEFT JOIN kategori k ON k.id_kategori=p.id_kategori ORDER BY p.id_produk DESC');$stats=mysqli_fetch_assoc(mysqli_query($koneksi,"SELECT COUNT(*) transaksi,COALESCE(SUM(CASE WHEN status IN ('dibayar','diproses','dikirim','selesai') THEN total ELSE 0 END),0) omzet FROM pesanan"));$title='Admin';require 'header.php';?><h2>Dashboard Admin</h2><?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="stats"><div class="stat">Transaksi<b><?=e($stats['transaksi'])?></b></div><div class="stat">Omzet<b><?=rupiah($stats['omzet'])?></b></div></div><div class="card"><h3>Tambah Produk</h3><form method="post"><input type="hidden" name="produk" value="1"><div class="grid"><input name="nama" placeholder="Nama produk" required><input name="harga" type="number" min="0" step="0.01" placeholder="Harga" required><input name="stok" type="number" min="0" placeholder="Stok" required><select name="kategori" required><?php while($c=mysqli_fetch_assoc($cats)):?><option value="<?=$c['id_kategori']?>"><?=e($c['nama_kategori'])?></option><?php endwhile;?></select></div><br><textarea name="deskripsi" placeholder="Deskripsi"></textarea><br><button class="btn">Simpan Produk</button></form></div><br><div class="table-wrap"><table><tr><th>Produk</th><th>Harga</th><th>Stok</th><th>Kategori</th><th>Aksi</th></tr><?php while($p=mysqli_fetch_assoc($products)):?><tr><td><?=e($p['nama_produk'])?></td><td><?=rupiah($p['harga'])?></td><td><?=$p['stok']?></td><td><?=e($p['nama_kategori']??'-')?></td><td><a class="btn danger small" onclick="return confirm('Hapus produk?')" href="?hapus_produk=<?=$p['id_produk']?>">Hapus</a></td></tr><?php endwhile;?></table></div><br><div class="card"><h3>Tambah Kategori</h3><form method="post" class="actions"><input type="hidden" name="kategori" value="1"><input name="nama_kategori" placeholder="Nama kategori" required><button class="btn">Tambah</button></form></div><br><a class="btn" href="laporan.php">Buka Laporan</a><?php require 'footer.php';?>
